-- Q) Add the studio's new production, Toy Story 4 to the list of movies (you can use any director)

-- alter table movies
-- alter column id add generated by default as identity;

-- Check the highest existing ID
SELECT MAX(id) FROM movies;

-- Check which sequence is attached to id
SELECT pg_get_serial_sequence('movies', 'id');

-- Synchronize the sequence with the existing data
SELECT setval(
    pg_get_serial_sequence('movies', 'id'),
    (SELECT MAX(id) FROM movies)
);

insert into movies (title,director,year,length_minutes)
values ('Toy Story 4', 'Hiralal Mehta', 2026, 550);

select * from movies;

